diff --git a/lib/backoff.js b/lib/backoff.js
index 4bb3dba..6447faa 100644
--- a/lib/backoff.js
+++ b/lib/backoff.js
@@ -1,4 +1,4 @@
 /** Delay in ms before retry number `attempt` (1 = the first retry): base * factor^(attempt-1), capped at max. */
 export function backoffDelay(attempt, { base = 100, factor = 2, max = 30000 } = {}) {
-  return Math.min(max, base * factor ** attempt);
+  return Math.min(max, base * factor ** (attempt - 1));
 }
